let malColores = 0;
esp.rejilla.forEach((fila, i) => {
  for (let j = 0; j < N; j++) {
    const c = hex(((filas[i] || {}).values || [])[j]?.effectiveFormat?.backgroundColor);
    if (c !== esp.colores[i][j]) malColores++;
    if (libre.has(i + ',' + j)) continue;
    const e = String(fila[j] ?? '');
    if (e !== leida[i][j]) { malValores++; if (ejemplos.length < 5) ejemplos.push([i + 1, j + 1, e.slice(0, 40), leida[i][j].slice(0, 40)]); }
  }
});
const grid = hoja.properties.gridProperties;
