  const total = Math.max(api.remolques_descarga.filas_minimas || 0, masTextos);
  const desde = filas.length;
  for (let i = 0; i < total; i++) {
    const fila = nuevaFila();
    if (i === 0) fila[0] = texto(api.remolques_descarga.etiqueta);
    api.dias.forEach((d, j) => { fila[2 + j] = texto((porDia[d.fecha] || [])[i]); });
    filas.push(fila);
  }
  bloques.push({ desde, hasta: filas.length, color: COLORES.remolques, borde: false });
}

// 2) Cargadores: tres filas cada uno.
api.cargadores.forEach((c) => {
  const desde = filas.length;
  const clave = 'C:' + c.codigo;
  const p = conservar(clave);
  const porFecha = {};
  (c.dias || []).forEach((d) => { porFecha[d.fecha] = d; });
  const f1 = nuevaFila(); const f2 = nuevaFila(); const f3 = nuevaFila();
  f1[0] = 'CARGADOR';
  f1[1] = texto(c.b_fila1);
  f1[COL_CLAVE] = clave;
  api.dias.forEach((d, j) => {
    f1[2 + j] = p.notas[j];
    f2[2 + j] = texto((porFecha[d.fecha] || {}).fila2);
    f3[2 + j] = texto((porFecha[d.fecha] || {}).fila3);
  });
  filas.push(f1, f2, f3);
  libres.push({ fila: desde, columnaDesde: 2, columnaHasta: 9, color: aclarar(COLORES.cargadores) });
  bloques.push({ desde, hasta: desde + 3, color: COLORES.cargadores, borde: true });
});

// 3-5) Diania, Marsaf y externos: tres filas cada vehículo.
let grupoAnterior = null;
let indiceGrupo = -1;
api.vehiculos.forEach((v) => {
  const desde = filas.length;
  const clave = 'V:' + v.codigo;
  const p = conservar(clave);
  let color;
  if (v.bloque === 'externo') {
    const grupo = v.grupo ? (v.grupo.codigo || v.grupo.nombre || '') : '';
    if (grupo !== grupoAnterior) { indiceGrupo += 1; grupoAnterior = grupo; }
    color = COLORES.externo[indiceGrupo % COLORES.externo.length];
  } else {
    color = COLORES[v.bloque];
  }
  const porFecha = {};
  (v.dias || []).forEach((d) => { porFecha[d.fecha] = d; });
  const f1 = nuevaFila(); const f2 = nuevaFila(); const f3 = nuevaFila();
  f1[0] = texto(v.a.fila1); f2[0] = resumirTaller(texto(v.a.fila2)); f3[0] = p.libreRemolque;
  f1[1] = texto(v.b.fila1); f2[1] = resumirTaller(texto(v.b.fila2)); f3[1] = texto(v.b.fila3);
  f1[COL_CLAVE] = clave;
  api.dias.forEach((d, j) => {
    f1[2 + j] = p.notas[j];
    f2[2 + j] = texto((porFecha[d.fecha] || {}).fila2);
    f3[2 + j] = texto((porFecha[d.fecha] || {}).fila3);
  });
  filas.push(f1, f2, f3);
  libres.push({ fila: desde, columnaDesde: 2, columnaHasta: 9, color: aclarar(color) });
  libres.push({ fila: desde + 2, columnaDesde: 0, columnaHasta: 1, color: aclarar(color) });
  if (f2[0]) rojas.push({ fila: desde + 1, columna: 0 });
  if (f2[1]) rojas.push({ fila: desde + 1, columna: 1 });
  bloques.push({ desde, hasta: desde + 3, color, borde: true });
});

const totalFilas = filas.length;
const filasHoja = Math.max(totalFilas + 20, 100);

// Color esperado de cada celda: el del bloque, más claro en las libres y rojo en las incidencias de taller.
const colores = filas.map((_, i) => {
  if (i === 0) return new Array(COLUMNAS).fill(COLORES.cabecera);
  const b = bloques.find((x) => i >= x.desde && i < x.hasta);
