});
libres.forEach((l) => { for (let j = l.columnaDesde; j < l.columnaHasta; j++) colores[l.fila][j] = l.color; });
rojas.forEach((r) => { colores[r.fila][r.columna] = COLORES.taller; });

// Sin cambios: si la pestaña ya existe y todas las celdas que vienen de Trans 2000 son iguales, no hay que escribir nada.
const esLibre = new Set();
libres.forEach((l) => { for (let j = l.columnaDesde; j < l.columnaHasta; j++) esLibre.add(l.fila + ',' + j); });
