}
requests.push({ updateSheetProperties: { properties: { sheetId, gridProperties: { rowCount: filasHoja, columnCount: COLUMNAS, frozenRowCount: 1, frozenColumnCount: FIJAS } }, fields: 'gridProperties.rowCount,gridProperties.columnCount,gridProperties.frozenRowCount,gridProperties.frozenColumnCount' } });
requests.push({ updateCells: { start: { sheetId, rowIndex: 0, columnIndex: 0 }, rows: filas.map((fila) => ({ values: fila.map(celda) })), fields: 'userEnteredValue' } });
const todo = { sheetId, startRowIndex: 0, endRowIndex: totalFilas, startColumnIndex: 0, endColumnIndex: COLUMNAS };
requests.push({ repeatCell: { range: { ...todo, startRowIndex: 1 }, cell: { userEnteredFormat: { verticalAlignment: 'TOP', wrapStrategy: 'WRAP' } }, fields: 'userEnteredFormat.verticalAlignment,userEnteredFormat.wrapStrategy' } });
requests.push({ repeatCell: { range: { ...todo, endRowIndex: 1 }, cell: { userEnteredFormat: { backgroundColor: rgb(COLORES.cabecera), horizontalAlignment: 'CENTER', verticalAlignment: 'MIDDLE', textFormat: { bold: true } } }, fields: 'userEnteredFormat.backgroundColor,userEnteredFormat.horizontalAlignment,userEnteredFormat.verticalAlignment,userEnteredFormat.textFormat.bold' } });
bloques.forEach((b) => {
  requests.push({ repeatCell: { range: { sheetId, startRowIndex: b.desde, endRowIndex: b.hasta, startColumnIndex: 0, endColumnIndex: COLUMNAS }, cell: { userEnteredFormat: { backgroundColor: rgb(b.color) } }, fields: 'userEnteredFormat.backgroundColor' } });
  if (b.borde) requests.push({ updateBorders: { range: { sheetId, startRowIndex: b.desde, endRowIndex: b.desde + 1, startColumnIndex: 0, endColumnIndex: COLUMNAS }, top: { style: 'SOLID', color: { red: 0.4, green: 0.4, blue: 0.4 } } } });
});
libres.forEach((l) => requests.push({ repeatCell: { range: { sheetId, startRowIndex: l.fila, endRowIndex: l.fila + 1, startColumnIndex: l.columnaDesde, endColumnIndex: l.columnaHasta }, cell: { userEnteredFormat: { backgroundColor: rgb(l.color) } }, fields: 'userEnteredFormat.backgroundColor' } }));
rojas.forEach((r) => requests.push({ repeatCell: { range: { sheetId, startRowIndex: r.fila, endRowIndex: r.fila + 1, startColumnIndex: r.columna, endColumnIndex: r.columna + 1 }, cell: { userEnteredFormat: { backgroundColor: rgb(COLORES.taller) } }, fields: 'userEnteredFormat.backgroundColor' } }));
[[0, 1, 200], [1, 2, 250], [2, 9, 230]].forEach(([ini, fin, px]) => requests.push({ updateDimensionProperties: { range: { sheetId, dimension: 'COLUMNS', startIndex: ini, endIndex: fin }, properties: { pixelSize: px }, fields: 'pixelSize' } }));
requests.push({ updateDimensionProperties: { range: { sheetId, dimension: 'COLUMNS', startIndex: COL_CLAVE, endIndex: COL_CLAVE + 1 }, properties: { hiddenByUser: true }, fields: 'hiddenByUser' } });
// Toda la pestaña bloqueada salvo las celdas libres (notas de cada día y «Libre» del remolque).
requests.push({ addProtectedRange: { protectedRange: {
  range: { sheetId },
  description: 'Planning de Trans 2000 (n8n): solo se editan las notas de cada día y «Libre»',
  warningOnly: false,
  unprotectedRanges: libres.map((l) => ({ sheetId, startRowIndex: l.fila, endRowIndex: l.fila + 1, startColumnIndex: l.columnaDesde, endColumnIndex: l.columnaHasta })),
} } });

return {
  sinCambios,
  batch: { requests },
  pestana: { titulo, sheetId, existia: !!existente },
  resumen: {
    semana: api.desde + ' a ' + api.hasta,
    remolques: (api.remolques_descarga.remolques || []).length,
    cargadores: api.cargadores.length,
    vehiculos: api.vehiculos.length,
    filas: totalFilas,
    celdas_libres_conservadas: conservadas,
    rangos_sin_bloquear: libres.length,
    celdas_taller_en_rojo: rojas.length,
    peticiones: requests.length,
  },
  rejilla: filas,
  colores,
  libres: libres.map((l) => ({ fila: l.fila, filas: 1, columnaDesde: l.columnaDesde, columnaHasta: l.columnaHasta })),
};
})();
